def IsEllOneLowerPart (S L : EllOneSum ℕ X →L[𝕜] EllOneSum ℕ X) : Prop :=
  ∀ j x, L (lp.single 1 j x) = S (lp.single 1 j x) -
    ∑ i ∈ Finset.range j, lp.single (E := fun _ : ℕ => X) 1 i (lpEntry S i j x)

