theorem IsEllOneLowerPart.single_apply {S L : EllOneSum ℕ X →L[𝕜] EllOneSum ℕ X}
    (hL : IsEllOneLowerPart S L) (j : ℕ) (x : X) (k : ℕ) :
    L (lp.single 1 j x) k = if j ≤ k then S (lp.single 1 j x) k else 0
